const dataUrl=f=>governedPortal&&f.startsWith('demonstration/')?'/platform/bi-demo/'+f.slice(14):ROOT+f;
async function load(k,f){if(!state.data[k]){const r=await fetch(dataUrl(f));if(!r.ok)throw Error(f);state.data[k]=parseCSV(await r.text())}return state.data[k]}
// Source of truth for the shared demonstration revenue: the DOCUMENT-grain
// journal has currency; daily and customer extracts do not. Never total EUR,
// USD and TND into a single "TND" amount.
async function tndJournal(){return (await load('journal_all','ventes/journal_ventes_2026_demo.csv')).filter(r=>r.devise==='TND')}
const mm=v=>Math.round(num(v)*1000);
async function tndDaily(){let m=new Map();for(const r of await tndJournal()){let x=m.get(r.date_facture)||{date_facture:r.date_facture,documents:0,ht_m:0,ttc_m:0,timbre_m:0};x.documents++;x.ht_m+=mm(r.montant_ht);x.ttc_m+=mm(r.montant_ttc);x.timbre_m+=mm(r.timbre);m.set(r.date_facture,x)}return [...m.values()].sort((a,b)=>a.date_facture.localeCompare(b.date_facture)).map(x=>({date_facture:x.date_facture,documents:x.documents,montant_ht:x.ht_m/1000,montant_ttc:x.ttc_m/1000,timbre:x.timbre_m/1000}))}
async function tndCustomers(){let m=new Map();for(const r of await tndJournal()){let x=m.get(r.client_id)||{client_id:r.client_id,documents:0,ht_m:0,ttc_m:0};x.documents++;x.ht_m+=mm(r.montant_ht);x.ttc_m+=mm(r.montant_ttc);m.set(r.client_id,x)}return [...m.values()].map(x=>({client_id:x.client_id,documents:x.documents,montant_ht:x.ht_m/1000,montant_ttc:x.ttc_m/1000}))}
function badge(t){let n=t.toLowerCase(),c=n.includes('simulation')||n.includes('prototype')?'demo':n.includes('extension')?'option':n.includes('rapprocher')||n.includes('confirmer')||n.includes('requise')?'warn':'ok';return `<span class="badge ${c}">${t}</span>`}function kpi(l,v,n='Source CSV'){return `<article class="kpi"><small>${l}</small><strong>${v}</strong><em>${n}</em></article>`}function panel(t,b,s='',v=''){return `<article class="panel"><div class="panel-head"><div><h3>${t}</h3><p>${s}</p></div>${v?badge(v):''}</div>${b}</article>`}function table(r,c,m=100){return r.length?`<div class="table-wrap"><table><thead><tr>${c.map(x=>`<th class="${x[2]||''}">${x[1]}</th>`).join('')}</tr></thead><tbody>${r.slice(0,m).map(y=>`<tr>${c.map(x=>`<td class="${x[2]||''}">${x[3]?x[3](y[x[0]]):y[x[0]]}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<div class="empty">Aucune donnee</div>'}
function agentCard(icon,name,role,status,detail){return `<article class="agent-card"><div class="agent-icon">${icon}</div><div class="agent-copy"><div class="agent-title"><h3>${name}</h3>${badge(status)}</div><p>${role}</p><small>${detail}</small></div></article>`}
function offerCard(name,status,value,needs,tag){return `<article class="offer-card"><div class="offer-top"><span class="offer-tag">${tag}</span>${badge(status)}</div><h3>${name}</h3><p>${value}</p><div class="offer-needs"><strong>Pre-requis</strong><span>${needs}</span></div><button class="offer-action" data-offer="${name}">Voir le perimetre</button></article>`}
function bars(r,l,v){const w=720,h=250,p=40,M=Math.max(...r.map(x=>num(x[v])),1),st=(w-p*2)/Math.max(r.length,1),bw=st*.65;return `<div class="chart"><svg viewBox="0 0 ${w} ${h}"><line class="axis" x1="${p}" y1="${h-p}" x2="${w-p}" y2="${h-p}"/>${r.map((x,i)=>{let z=num(x[v]),hh=(h-p*2)*z/M,xx=p+i*st+st*.16,y=h-p-hh;return `<g class="bar-group" data-key="${x[l]}"><rect class="bar" x="${xx}" y="${y}" width="${bw}" height="${hh}" rx="3"><title>${x[l]} - ${fmt(z)}</title></rect><text class="tick" x="${xx+bw/2}" y="${h-12}" text-anchor="middle">${String(x[l]).slice(0,11)}</text></g>`}).join('')}</svg></div>`}
function line(r,l,v){if(r.length>60)r=Object.values(r.reduce((a,x)=>{let k=String(x[l]).slice(0,7);a[k]??={[l]:k,[v]:0};a[k][v]+=num(x[v]);return a},{}));const w=720,h=250,p=40,M=Math.max(...r.map(x=>num(x[v])),1),X=i=>p+i*(w-p*2)/Math.max(r.length-1,1),Y=z=>h-p-num(z)/M*(h-p*2),pts=r.map((x,i)=>`${X(i)},${Y(x[v])}`).join(' ');return `<div class="chart"><svg viewBox="0 0 ${w} ${h}" role="img"><line class="axis" x1="${p}" y1="${h-p}" x2="${w-p}" y2="${h-p}"/><polyline class="line" points="${pts}"/>${r.map((x,i)=>`<circle class="point" cx="${X(i)}" cy="${Y(x[v])}" r="4"><title>${x[l]} - ${fmt(x[v])}</title></circle><text class="tick" x="${X(i)}" y="${h-12}" text-anchor="middle">${String(x[l]).slice(0,7)}</text>`).join('')}</svg></div>`}
function filters(d){$('#filters').innerHTML=d.map(x=>`<label>${x.label}<select data-filter="${x.key}">${x.options.map(o=>`<option value="${o}">${o||'Tous'}</option>`).join('')}</select></label>`).join('');$('#filters').style.display=d.length?'flex':'none';document.querySelectorAll('[data-filter]').forEach(e=>{e.value=state.filter[e.dataset.filter]||'';e.onchange=()=>{state.filter[e.dataset.filter]=e.value;render()}})}const cards=a=>`<div class="grid kpis">${a.join('')}</div>`;
async function overview(){let d=await load('daily',sources.overview.file),c=await load('cash',sources.cash.file),ht=sum(d,'montant_ht'),docs=sum(d,'documents');filters([]);return cards([kpi('CA HT',money(ht)),kpi('CA TTC TND',money(sum(d,'montant_ttc'))),kpi('Documents',fmt(docs,0)),kpi('Panier moyen',money(ht/docs)),kpi('Encaissements (unité à confirmer)',fmt(sum(c,'montant'))+' (devise non précisée)')])+`<div class="grid panels-2">${panel('Trajectoire du CA TND',line(d.map(x=>({x:x.date_facture,v:num(x.montant_ht)})),'x','v'),'HT quotidien',sources.overview.status)}${panel('Encaissements',bars(c.map(x=>({x:x.mois,v:num(x.montant)})),'x','v'),'Par mois',sources.cash.status)}</div>`}
async function sales(){let r=(await tndJournal()).filter(x=>x.date_facture>='2026-10-01'&&x.date_facture<='2026-10-20'),o=['',...new Set(r.map(x=>x.serie))];filters([{label:'Serie',key:'serie',options:o}]);if(state.filter.serie)r=r.filter(x=>x.serie===state.filter.serie);let ht=sum(r,'montant_ht'),daily=Object.values(r.reduce((a,x)=>{a[x.date_facture]??={x:x.date_facture,v:0};a[x.date_facture].v+=num(x.montant_ht);return a},{}));return cards([kpi('CA HT',money(ht)),kpi('CA TTC',money(sum(r,'montant_ttc'))),kpi('Documents',fmt(r.length,0)),kpi('Panier moyen',money(ht/r.length)),kpi('Timbres',money(sum(r,'timbre')))])+panel('CA HT quotidien',line(daily,'x','v'),'1er au 20 octobre 2026',sources.sales.status)+panel('Documents',table(r,[['date_facture','Date'],['document_id','Document'],['serie','Serie'],['client_id','Client'],['montant_ht','HT','num',money],['montant_ttc','TTC','num',money]]))}
async function clients(){let r=await tndCustomers(),ranked=[...r].sort((a,b)=>num(b.montant_ht)-num(a.montant_ht)),t=sum(r,'montant_ht');filters([]);return cards([kpi('CA HT',money(t)),kpi('Clients',fmt(r.length,0)),kpi('Part Top 10',fmt(sum(ranked.slice(0,10),'montant_ht')/t*100,1)+' %'),kpi('CA moyen',money(t/r.length))])+`<div class="grid panels-2">${panel('Pareto clients',bars(ranked.slice(0,15).map(x=>({x:x.client_id,v:x.montant_ht})),'x','v'),'Top clients par CA HT',sources.clients.status)}${panel('Detail clients',table(ranked,[['client_id','Client'],['documents','Documents'],['montant_ht','HT','num',money],['montant_ttc','TTC','num',money]]))}</div>`}
async function articles(){let r=await load('articles',sources.articles.file),o=['',...new Set(r.map(x=>x.famille_id).filter(Boolean))];filters([{label:'Famille',key:'famille',options:o}]);if(state.filter.famille)r=r.filter(x=>x.famille_id===state.filter.famille);let ranked=[...r].sort((a,b)=>num(b.montant_ht)-num(a.montant_ht));return cards([kpi('CA HT',money(sum(r,'montant_ht'))),kpi('Articles',fmt(r.length,0)),kpi('Quantite',fmt(sum(r,'quantite'))),kpi('Documents',fmt(sum(r,'documents'),0))])+panel('Articles contributeurs',bars(ranked.slice(0,18).map(x=>({x:x.article_id,v:x.montant_ht})),'x','v'),'Top articles par CA HT',sources.articles.status)+panel('Detail articles',table(ranked,[['article_id','Article'],['famille_id','Famille'],['quantite','Quantite','num',fmt],['montant_ht','HT','num',money],['documents','Documents']]))}
