function comboChart(){let vals=[.42,.5,.59,.55,.62,.58,.68,.74,.81,.92,1.02,.95],m=[8,10,11,10,11,10,12,14,15,17,18,16],w=700,h=250,p=42,step=(w-p*2)/12,months=['Jan','Fev','Mar','Avr','Mai','Juin','Juil','Aou','Sep','Oct','Nov','Dec'];return `<div class="combo-chart"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Evolution mensuelle du chiffre d'affaires et de la marge"><g class="grid-lines"><line x1="${p}" y1="60" x2="${w-p}" y2="60"/><line x1="${p}" y1="110" x2="${w-p}" y2="110"/><line x1="${p}" y1="160" x2="${w-p}" y2="160"/><line x1="${p}" y1="215" x2="${w-p}" y2="215"/></g><g class="combo-bars">${vals.map((v,i)=>`<rect x="${p+i*step+8}" y="${h-35-v*155}" width="${step-15}" height="${v*155}" rx="3"/>`).join('')}</g><polyline class="margin-line" points="${m.map((v,i)=>`${p+i*step+step/2},${h-35-v*7.5}`).join(' ')}"/>${m.map((v,i)=>`<circle cx="${p+i*step+step/2}" cy="${h-35-v*7.5}" r="4"/>`).join('')}${months.map((x,i)=>`<text x="${p+i*step+step/2}" y="238" text-anchor="middle">${x}</text>`).join('')}</svg><div class="chart-key"><span><i></i>Chiffre d'affaires (M TND)</span><span><i></i>Taux de marge (%)</span></div></div>`}
